        if (csr_num_e'(instr_rdata_iB[31:20])==CSR_MSTATUS||csr_num_e'(instr_rdata_iB[31:20])==CSR_MIE||csr_num_e'(instr_rdata_iB[31:20])==CSR_MSECCFG||instr_rdata_iB[31:25]==7'h1D)
