          end

      end
    else
      if (csr_op_en_oB==1'b1&&csr_op_oB!=CSR_OP_READ)
        begin
          if (csr_num_e'(instr_rdata_iB[31:20])==CSR_DCSR||csr_num_e'(instr_rdata_iB[31:20])==CSR_DPC||csr_num_e'(instr_rdata_iB[31:20])==CSR_DSCRATCH0||csr_num_e'(instr_rdata_iB[31:20])==CSR_DSCRATCH1)
            begin
