assign branch_jump_set_done_dB =  (branch_set_rawB|jump_set_rawB|branch_jump_set_done_qVotedB) &~instr_valid_clear_oB;
assign branch_jump_set_done_dC =  (branch_set_rawC|jump_set_rawC|branch_jump_set_done_qVotedC) &~instr_valid_clear_oC;

