assign branch_setA = branch_set_rawA&~branch_jump_set_done_qVotedA;
assign branch_setB = branch_set_rawB&~branch_jump_set_done_qVotedB;
assign branch_setC = branch_set_rawC&~branch_jump_set_done_qVotedC;
id_fsm_e id_fsm_qA, id_fsm_dA, id_fsm_qVotedA;
id_fsm_e id_fsm_qB, id_fsm_dB, id_fsm_qVotedB;
id_fsm_e id_fsm_qC, id_fsm_dC, id_fsm_qVotedC;

always_ff @( posedge clk_iA or negedge rst_niA )
  begin : id_pipeline_regA
    if (!rst_niA)
      begin
        id_fsm_qA <= FIRST_CYCLE;
      end
    else
      if (instr_executingA)
        begin
          id_fsm_qA <= id_fsm_dA;
        end

  end

always_ff @( posedge clk_iB or negedge rst_niB )
  begin : id_pipeline_regB
    if (!rst_niB)
      begin
        id_fsm_qB <= FIRST_CYCLE;
      end
    else
      if (instr_executingB)
        begin
          id_fsm_qB <= id_fsm_dB;
        end

  end

always_ff @( posedge clk_iC or negedge rst_niC )
  begin : id_pipeline_regC
    if (!rst_niC)
      begin
        id_fsm_qC <= FIRST_CYCLE;
      end
    else
      if (instr_executingC)
        begin
          id_fsm_qC <= id_fsm_dC;
        end

  end

always_comb
  begin
    id_fsm_dA = id_fsm_qVotedA;
    rf_we_rawA = rf_we_decA;
    stall_multdivA = 1'b0;
    stall_jumpA = 1'b0;
    stall_branchA = 1'b0;
    stall_aluA = 1'b0;
    branch_set_raw_dA = 1'b0;
    jump_set_rawA = 1'b0;
    perf_branch_oA = 1'b0;
    if (instr_executing_specA)
      begin
        unique case (id_fsm_qVotedA)
          FIRST_CYCLE : 
            begin
              unique case (1'b1)
                lsu_req_decA: begin
                  begin
                    id_fsm_dA = MULTI_CYCLE;
                  end
                end
                multdiv_en_decA: begin
                  if (~ex_valid_iA)
                    begin
                      id_fsm_dA = MULTI_CYCLE;
                      rf_we_rawA = 1'b0;
                      stall_multdivA = 1'b1;
                    end
                end
                branch_in_decA: begin
                  id_fsm_dA = (branch_decision_iA) ? MULTI_CYCLE : FIRST_CYCLE;
                  stall_branchA = branch_decision_iA;
                  branch_set_raw_dA = branch_decision_iA;
                  perf_branch_oA = 1'b1;
                end
                jump_in_decA: begin
                  id_fsm_dA = MULTI_CYCLE;
                  stall_jumpA = 1'b1;
                  jump_set_rawA = jump_set_decA;
                end
                alu_multicycle_decA: begin
                  stall_aluA = 1'b1;
                  id_fsm_dA = MULTI_CYCLE;
                  rf_we_rawA = 1'b0;
                end
                default: begin
                  id_fsm_dA = FIRST_CYCLE;
                end
              endcase
            end
          MULTI_CYCLE : 
            begin
              if (multdiv_en_decA)
                begin
                  rf_we_rawA = rf_we_decA&ex_valid_iA;
                end

              if (multicycle_doneA)
                begin
                  id_fsm_dA = FIRST_CYCLE;
                end
              else
                begin
                  stall_multdivA = multdiv_en_decA;
                  stall_branchA = branch_in_decA;
                  stall_jumpA = jump_in_decA;
                end
            end
          default : 
            begin
              id_fsm_dA = FIRST_CYCLE;
            end
        endcase
      end

  end

always_comb
  begin
    id_fsm_dB = id_fsm_qVotedB;
    rf_we_rawB = rf_we_decB;
    stall_multdivB = 1'b0;
    stall_jumpB = 1'b0;
    stall_branchB = 1'b0;
    stall_aluB = 1'b0;
    branch_set_raw_dB = 1'b0;
    jump_set_rawB = 1'b0;
    perf_branch_oB = 1'b0;
    if (instr_executing_specB)
      begin
        unique case (id_fsm_qVotedB)
          FIRST_CYCLE : 
            begin
              unique case (1'b1)
                lsu_req_decB: begin
                  begin
                    id_fsm_dB = MULTI_CYCLE;
                  end
                end
                multdiv_en_decB: begin
                  if (~ex_valid_iB) begin
                    id_fsm_dB = MULTI_CYCLE;
                    rf_we_rawB = 1'b0;
                    stall_multdivB = 1'b1;
                  end
                end
                branch_in_decB: begin
                  id_fsm_dB = (branch_decision_iB) ? MULTI_CYCLE : FIRST_CYCLE;
                  stall_branchB = branch_decision_iB;
                  branch_set_raw_dB = branch_decision_iB;
                  perf_branch_oB = 1'b1;
                end
                jump_in_decB: begin
                  id_fsm_dB = MULTI_CYCLE;
                  stall_jumpB = 1'b1;
                  jump_set_rawB = jump_set_decB;
                end
                alu_multicycle_decB: begin
                  stall_aluB = 1'b1;
                  id_fsm_dB = MULTI_CYCLE;
                  rf_we_rawB = 1'b0;
                end
                default: begin
                  id_fsm_dB = FIRST_CYCLE;
                end
              endcase
            end
          MULTI_CYCLE : 
            begin
              if (multdiv_en_decB)
                begin
                  rf_we_rawB = rf_we_decB&ex_valid_iB;
                end

              if (multicycle_doneB)
                begin
                  id_fsm_dB = FIRST_CYCLE;
                end
              else
                begin
                  stall_multdivB = multdiv_en_decB;
                  stall_branchB = branch_in_decB;
                  stall_jumpB = jump_in_decB;
                end
            end
          default : 
            begin
              id_fsm_dB = FIRST_CYCLE;
            end
        endcase
      end

  end

always_comb
  begin
    id_fsm_dC = id_fsm_qVotedC;
    rf_we_rawC = rf_we_decC;
    stall_multdivC = 1'b0;
    stall_jumpC = 1'b0;
    stall_branchC = 1'b0;
    stall_aluC = 1'b0;
    branch_set_raw_dC = 1'b0;
    jump_set_rawC = 1'b0;
    perf_branch_oC = 1'b0;
    if (instr_executing_specC)
      begin
        unique case (id_fsm_qVotedC)
          FIRST_CYCLE : 
            begin
              unique case (1'b1)
                lsu_req_decC: begin
                  begin
                    id_fsm_dC = MULTI_CYCLE;
                  end
                end 
                multdiv_en_decC: begin
                  if (~ex_valid_iC)
                    begin
                      id_fsm_dC = MULTI_CYCLE;
                      rf_we_rawC = 1'b0;
                      stall_multdivC = 1'b1;
                    end
                end
                branch_in_decC: begin
                  id_fsm_dC = (branch_decision_iC) ? MULTI_CYCLE : FIRST_CYCLE;
                  stall_branchC = branch_decision_iC;
                  branch_set_raw_dC = branch_decision_iC;
                  perf_branch_oC = 1'b1;
                end
                jump_in_decC: begin
                  id_fsm_dC = MULTI_CYCLE;
                  stall_jumpC = 1'b1;
                  jump_set_rawC = jump_set_decC;
                end
                alu_multicycle_decC: begin
                  stall_aluC = 1'b1;
                  id_fsm_dC = MULTI_CYCLE;
                  rf_we_rawC = 1'b0;
                end
                default: begin
                  id_fsm_dC = FIRST_CYCLE;
                end
              endcase
            end
          MULTI_CYCLE : 
            begin
              if (multdiv_en_decC)
                begin
                  rf_we_rawC = rf_we_decC&ex_valid_iC;
                end

              if (multicycle_doneC)
                begin
                  id_fsm_dC = FIRST_CYCLE;
                end
              else
                begin
                  stall_multdivC = multdiv_en_decC;
                  stall_branchC = branch_in_decC;
                  stall_jumpC = jump_in_decC;
                end
            end
          default : 
            begin
              id_fsm_dC = FIRST_CYCLE;
            end
        endcase
      end

  end
assign stall_idA = stall_memA|stall_multdivA|stall_jumpA|stall_branchA|stall_aluA;
assign stall_idB = stall_memB|stall_multdivB|stall_jumpB|stall_branchB|stall_aluB;
assign stall_idC = stall_memC|stall_multdivC|stall_jumpC|stall_branchC|stall_aluC;
assign instr_doneA = ~stall_idA&~flush_idA&instr_executingA;
assign instr_doneB = ~stall_idB&~flush_idB&instr_executingB;
assign instr_doneC = ~stall_idC&~flush_idC&instr_executingC;
assign instr_first_cycleA = instr_valid_iA& (id_fsm_qVotedA==FIRST_CYCLE) ;
assign instr_first_cycleB = instr_valid_iB& (id_fsm_qVotedB==FIRST_CYCLE) ;
assign instr_first_cycleC = instr_valid_iC& (id_fsm_qVotedC==FIRST_CYCLE) ;
assign instr_first_cycle_id_oA = instr_first_cycleA;
assign instr_first_cycle_id_oB = instr_first_cycleB;
assign instr_first_cycle_id_oC = instr_first_cycleC;
assign multicycle_doneA = lsu_req_decA ? lsu_resp_valid_iA : ex_valid_iA;
assign multicycle_doneB = lsu_req_decB ? lsu_resp_valid_iB : ex_valid_iB;
assign multicycle_doneC = lsu_req_decC ? lsu_resp_valid_iC : ex_valid_iC;
assign data_req_allowedA = instr_first_cycleA;
assign data_req_allowedB = instr_first_cycleB;
assign data_req_allowedC = instr_first_cycleC;
assign stall_memA = instr_valid_iA& (lsu_req_decA&(~ lsu_resp_valid_iA | instr_first_cycleA )) ;
assign stall_memB = instr_valid_iB& (lsu_req_decB&(~ lsu_resp_valid_iB | instr_first_cycleB )) ;
assign stall_memC = instr_valid_iC& (lsu_req_decC&(~ lsu_resp_valid_iC | instr_first_cycleC )) ;
assign instr_executing_specA = instr_valid_iA&~instr_fetch_err_iA&controller_runA;
assign instr_executing_specB = instr_valid_iB&~instr_fetch_err_iB&controller_runB;
assign instr_executing_specC = instr_valid_iC&~instr_fetch_err_iC&controller_runC;
assign instr_executingA = instr_executing_specA;
assign instr_executingB = instr_executing_specB;
assign instr_executingC = instr_executing_specC;
assign rf_rdata_a_fwdA = rf_rdata_a_iA;
assign rf_rdata_a_fwdB = rf_rdata_a_iB;
assign rf_rdata_a_fwdC = rf_rdata_a_iC;
assign rf_rdata_b_fwdA = rf_rdata_b_iA;
assign rf_rdata_b_fwdB = rf_rdata_b_iB;
assign rf_rdata_b_fwdC = rf_rdata_b_iC;
logic unused_data_req_done_exA;
logic unused_data_req_done_exB;
logic unused_data_req_done_exC;
assign perf_dside_wait_oA = instr_executingA&lsu_req_decA&~lsu_resp_valid_iA;
assign perf_dside_wait_oB = instr_executingB&lsu_req_decB&~lsu_resp_valid_iB;
assign perf_dside_wait_oC = instr_executingC&lsu_req_decC&~lsu_resp_valid_iC;
assign instr_id_done_oA = instr_doneA;
assign instr_id_done_oB = instr_doneB;
assign instr_id_done_oC = instr_doneC;
assign instr_perf_count_id_oA = ~ebrk_insnA&~ecall_insn_decA&~illegal_insn_decA&~ (dret_insn_decA&~debug_mode_oA) &~illegal_csr_insn_iA&~instr_fetch_err_iA;
assign instr_perf_count_id_oB = ~ebrk_insnB&~ecall_insn_decB&~illegal_insn_decB&~ (dret_insn_decB&~debug_mode_oB) &~illegal_csr_insn_iB&~instr_fetch_err_iB;
assign instr_perf_count_id_oC = ~ebrk_insnC&~ecall_insn_decC&~illegal_insn_decC&~ (dret_insn_decC&~debug_mode_oC) &~illegal_csr_insn_iC&~instr_fetch_err_iC;
assign en_wb_oA = instr_doneA;
assign en_wb_oB = instr_doneB;
assign en_wb_oC = instr_doneC;
assign perf_wfi_wait_oA = wfi_insn_decA;
assign perf_wfi_wait_oB = wfi_insn_decB;
assign perf_wfi_wait_oC = wfi_insn_decC;
assign perf_div_wait_oA = stall_multdivA&div_en_decA;
assign perf_div_wait_oB = stall_multdivB&div_en_decB;
assign perf_div_wait_oC = stall_multdivC&div_en_decC;

majorityVoter branch_jump_set_done_qVoterA (
    .inA(branch_jump_set_done_qA),
